3	import java.io.IOException;
4	import java.io.UncheckedIOException;
5	import java.nio.charset.StandardCharsets;
6	import java.nio.file.Files;
7	import java.nio.file.Path;
8	import java.nio.file.StandardOpenOption;
9	import org.springframework.beans.factory.annotation.Value;
10	import org.springframework.stereotype.Service;
11	
12	/**
13	 * Audit sink: appends one record per line to a KNOWN FILE (app.audit.file, default .run/audit.log)
14	 * so tests can assert side-effects by reading that file — the second test-assertion channel
15	 * alongside the UI. The file path + one-record-per-line format is a stable contract, like
16	 * data-testid: features may be rewritten as long as they keep emitting the agreed records.
17	 *
18	 * Inject this bean into any feature that must record an audit entry. Each write flushes (append +
19	 * SYNC) so a test reads the record immediately.
20	 */
21	@Service
22	public class Audit {
23	
24	    private final Path file;
25	
26	    public Audit(@Value("${app.audit.file:.run/audit.log}") String path) {
27	        this.file = Path.of(path);
28	    }
29	
30	    /** Append one audit record. Tests assert the exact line(s) in the file. */
31	    public synchronized void record(String entry) {
32	        try {
33	            Path parent = file.toAbsolutePath().getParent();
34	            if (parent != null) {
35	                Files.createDirectories(parent);
36	            }
37	            Files.writeString(file, entry + System.lineSeparator(), StandardCharsets.UTF_8,
38	                    StandardOpenOption.CREATE, StandardOpenOption.APPEND, StandardOpenOption.SYNC);
39	        } catch (IOException e) {
40	            throw new UncheckedIOException(e);
41	        }
42	    }
43	
44	    /** Truncate the audit file. */
45	    public synchronized void clear() {
46	        try {
47	            Files.deleteIfExists(file);
48	        } catch (IOException e) {
49	            throw new UncheckedIOException(e);
50	        }
51	    }
52	}
