186	import java.util.List;
187	import java.util.Locale;
188	import net.officefloor.hq.app.sheet.SheetService;
189	import org.springframework.dao.DataIntegrityViolationException;
190	import org.springframework.http.HttpStatus;
191	import org.springframework.stereotype.Service;
192	import org.springframework.transaction.annotation.Transactional;
193	import org.springframework.web.server.ResponseStatusException;
194	
195	@Service
196	public class PersonService {
197	
198	    private final PersonRepository people;
199	    private final SheetService sheets;
200	
201	    public PersonService(PersonRepository people, SheetService sheets) {
202	        this.people = people;
203	        this.sheets = sheets;
204	    }
205	
206	    /** The sheet's people, in the order they were added. */
207	    @Transactional(readOnly = true)
208	    public List<Person> list(String sheetId) {
209	        return people.findBySheetIdOrderByIdAsc(sheetId);
210	    }
211	
212	    /** Add a person (the sheet is started when it was never loaded before). */
213	    @Transactional
214	    public Person add(String sheetId, String user, String name, Grade grade) {
215	        sheets.load(sheetId, user);
216	        String trimmed = name.trim();
217	        requireUnusedName(sheetId, null, trimmed);
218	        try {
219	            return people.saveAndFlush(new Person(sheetId, trimmed, grade));
220	        } catch (DataIntegrityViolationException e) {
221	            throw nameInUse();
222	        }
223	    }
224	
225	    /** Change a person's name and grade. */
226	    @Transactional
227	    public Person edit(String sheetId, long personId, String name, Grade grade) {
228	        Person person = people.findByIdAndSheetId(personId, sheetId)
229	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
230	        String trimmed = name.trim();
231	        requireUnusedName(sheetId, personId, trimmed);
232	        person.setName(trimmed);
233	        person.setGrade(grade);
234	        try {
235	            return people.saveAndFlush(person);
236	        } catch (DataIntegrityViolationException e) {
237	            throw nameInUse();
238	        }
239	    }
240	
241	    /** Refuse a name another person on the sheet already has, ignoring case. */
242	    private void requireUnusedName(String sheetId, Long personId, String name) {
243	        String key = name.toLowerCase(Locale.ROOT);
244	        boolean used = people.findBySheetIdOrderByIdAsc(sheetId).stream()
245	                .anyMatch(p -> !p.getId().equals(personId) && p.getName().toLowerCase(Locale.ROOT).equals(key));
246	        if (used) throw nameInUse();
247	    }
248	
249	    private static ResponseStatusException nameInUse() {
250	        return new ResponseStatusException(HttpStatus.CONFLICT, "That name is already in use");
251	    }
252	}
