419	@Service
420	public class ClaimService {
421	
422	    private final ClaimRepository claims;
423	    private final PersonRepository people;
424	    private final SheetService sheets;
425	
426	    public ClaimService(ClaimRepository claims, PersonRepository people, SheetService sheets) {
427	        this.claims = claims;
428	        this.people = people;
429	        this.sheets = sheets;
430	    }
431	
432	    /** The sheet's claims, newest first. */
433	    @Transactional(readOnly = true)
434	    public List<Claim> list(String sheetId) {
435	        return claims.findBySheetIdOrderByIdDesc(sheetId);
436	    }
437	
438	    /** Add a claim for a person; without a date it is dated the sheet's today. */
439	    @Transactional
440	    public Claim add(String sheetId, long personId, BigDecimal amount, LocalDate date, String note) {
441	        people.findByIdAndSheetId(personId, sheetId)
442	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
443	        return claims.saveAndFlush(new Claim(sheetId, personId, amount, dateOrToday(sheetId, date), noteOf(note)));
444	    }
445	
446	    /** Change a claim's amount, date and note; without a date it is dated the sheet's today. */
447	    @Transactional
448	    public Claim edit(String sheetId, long claimId, BigDecimal amount, LocalDate date, String note) {
449	        Claim claim = claims.findByIdAndSheetId(claimId, sheetId)
450	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
451	        claim.setAmount(amount);
452	        claim.setDate(dateOrToday(sheetId, date));
453	        claim.setNote(noteOf(note));
454	        return claims.saveAndFlush(claim);
455	    }
456	
457	    private LocalDate dateOrToday(String sheetId, LocalDate date) {
458	        return date != null ? date : sheets.today(sheetId);
459	    }
460	
461	    private static String noteOf(String note) {
462	        return note == null ? "" : note.trim();
463	    }
464	}
